/*
This func will transform a json object to a insert statement.
The statement is copied to msg.query

JSON schema:

{
    "schema": "schema",
    "table": "schema",
    "columns": ["columns1", "comlumns2"],
    "values": ["value1", 100]
}
*/

var schema = msg.sql.schema;
var table = msg.sql.table;
var columns = msg.sql.columns.join(", ");
var values = msg.sql.values;

// check if value is of type string and add single quotes if so
var sqlValues = values.map(value => {
    return typeof value === 'string' ? `'${value}'` : value;
}).join(", ");

// 
var query = `INSERT INTO ${schema}.${table} (${columns}) VALUES (${sqlValues});`;

msg.query = query;
return msg;

const device_id = msg.payload.device_id;
const ts = msg.payload.timestamp;
let day_name = msg.day;
let payload = msg.payload;

// get context variable
const context_name = device_id + "_time";
let time_context = context.get(context_name);
if (!time_context) {
    let template = context.get("template");
    time_context = JSON.parse(JSON.stringify(template));  // Deep clone
}
time_context.device_id = device_id;

node.send([null, msg.payload])

switch (msg.type) {
    case "day":
        const days = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
        days.forEach(day => {
            if (!time_context[day]) {
                node.error("time context is not defined!", msg);
            }
            let active_old = time_context[day]?.active;
            time_context[day].ts = ts;
            time_context[day].active = payload[day];  // Store boolean value in context
            // If active bool flag has changed send the msg to next node
            if (active_old != payload[day] || active_old == undefined) {
                msg.payload = time_context[day];
                msg.payload.device_id = device_id;
                node.send(msg);
            }
        }
        )
        break;
    case "ein":
        time_context[day_name].ts = ts;
        time_context[day_name].on_time = payload.value;
        time_context[day_name].device_id = device_id;
        msg.payload = time_context[day_name];
        node.send(msg);
        break;
    case "aus":
        time_context[day_name].ts = ts;
        time_context[day_name].off_time = payload.value;
        time_context[day_name].device_id = device_id;
        msg.payload = time_context[day_name];
        node.send(msg);
        break;
    default:
        return null;
}

context.set(context_name, time_context);
return null;

