/*
In diesem Node wird das message Objekt transformiert, sodass es an die Datenbank weitergeleitet wird.
Beispiel des eingehenden Objekts:

{
    "topic":"test/polipol/6988/state/Betriebsbereit",
    "payload": {
        "test/polipol/6988/state/Betriebsbereit": {
            "device_id":"6988","timestamp":"2025-07-09T07:07:19.894475Z","name":"Betriebsbereit","value":true
        },
        "test/polipol/6988/signal/Schmelzbehaelter_Heizmodul_act": {
            "device_id":"6988","timestamp":"2025-07-09T07:06:22.518609Z","name":"Schmelzbehaelter_Heizmodul_act","value":false
        },
        "test/polipol/6988/state/Pause": {
            "device_id":"6988","timestamp":"2025-07-09T07:07:19.894537Z","name":"Pause","value":true
        }
    },
    "qos":0,
    "retain":false,
    "_msgid":"fc0c37aa74b84588"
}
*/
// context store to check datachange
const latest_payload = context.get("latest_payload") || {};
// store useful variables
const topic = msg.topic;
const payload = msg.payload;
const device_id = payload[topic].device_id;  // Assume all keys in payload share the same device_id
const timestamp = payload[topic].timestamp;  // timestamp of topic
let stueckzahlTs = null;

// Object for new payload
let new_payload = {
    device_id: device_id,
    ts: timestamp
}

// process each entry
for (let key in payload) {
    let entry = payload[key];  // get entry
    // Only continue if 'name' and 'value' exist
    if (entry && entry.name !== undefined && entry.value !== undefined) {
        const name = entry.name;
        const value = entry.value;
        // Store specific values
        if (["Betriebsbereit", "Pause", "Schmelzbehaelter_Heizmodul_act"].includes(name)) {
            new_payload[name] = value;
        }
        // Add opc_disconnected by toggle the boolean of connection
        // connection = true RESULTS IN opc_disconnected = false
        if (name === "connection") {
            new_payload["opc_disconnected"] = !value;
        }
        // Add timestamp of latest stueckzahl
        if (name === "Stueckzahl") {
            stueckzahlTs = new Date(entry.timestamp).getTime();
        }
    }
}

// add opc_disconnected if its missing
if (typeof new_payload.opc_disconnected === 'undefined') {
    new_payload.opc_disconnected = false;
}
// if opc_disconnected = true, set all other values to false
if (new_payload.opc_disconnected) {
    for (let key of ["Betriebsbereit", "Pause", "Schmelzbehaelter_Heizmodul_act", "in_production"]){
        new_payload[key] = false
    }
}
// Add in_production logic
else if (stueckzahlTs) {
    const now = new Date(payload[topic].timestamp).getTime()
    const diffMinutes = (now - stueckzahlTs) / (1000 * 60);
    new_payload.in_production = diffMinutes <= 3;
} else {
    new_payload.in_production = false;
}

// Check if data have changed since last datachange
if (
    new_payload.Betriebsbereit != latest_payload.Betriebsbereit ||
    new_payload.Schmelzbehaelter_Heizmodul_act != latest_payload.Schmelzbehaelter_Heizmodul_act ||
    new_payload.Pause != latest_payload.Pause ||
    new_payload.in_production != latest_payload.in_production ||
    new_payload.opc_disconnected != latest_payload.opc_disconnected
) {
    msg.payload = new_payload;
    context.set("latest_payload", new_payload);  // store context variable
    return msg;
} else {
    return null;
}

