};

function adjustDate(dateStr) {
    if (!dateStr) return "";
    let parts = dateStr.split(".");
    if (parts.length < 2) return dateStr; // Kein valides Datum
    let day = parseInt(parts[0], 10);
    let month = parseInt(parts[1], 10);
    let year = parts.length > 2 ? parseInt(parts[2], 10) : null;

    if (!year) {
        if (month === 1 && (now.getMonth() + 1 === 11 || now.getMonth() + 1 === 12)) {
            year = now.getFullYear() + 1;
        } else if (month === 12 && (now.getMonth() + 1 >= 1 && now.getMonth() + 1 <= 3)) {
            year = now.getFullYear() - 1;
        } else {
            year = now.getFullYear();
        }
    }
    return ("0" + day).slice(-2) + "." + ("0" + month).slice(-2) + "." + year;
}

function parseDate(dateStr) {
    if (!dateStr) return null;
    let parts = dateStr.split(".");
    if (parts.length < 3) return null;
    let day = parseInt(parts[0], 10);
    let month = parseInt(parts[1], 10) - 1; // JS: 0-basiert
    let year = parseInt(parts[2], 10);
    let d = new Date(year, month, day);
    // Prüfe, ob gültiges Datum
    if (isNaN(d.getTime())) return null;
    return d;
}

