    let row = rows[i];
    if (!row || !row[map.tour] || !row[map.tourdatum]) continue;

    let tour = String(row[map.tour]).replace(/\//g, '_');
    let beladedatum = adjustDate(row[map.beladedatum] || "");
    let tourdatum = adjustDate(row[map.tourdatum] || "");
    let prognose = map.prognose !== null ? (row[map.prognose] || "") : "";
    let ist = map.ist !== null ? (row[map.ist] || "") : "";
    let status = row[map.status] || "";

    let tourDateObj = parseDate(tourdatum);
    if (!tourDateObj) continue;
    let diff = now.getTime() - tourDateObj.getTime();

    if (diff > FOUR_WEEKS_MS && tourDateObj < now) {
        continue;
    }

    let topic = `polipol/${werk}/mag/mag-mag/tour/${tour}_${tourdatum}_${werk}/gsheet`;

    let payload = {
        tour: tour,
        tourdatum: tourdatum,
        beladedatum: beladedatum,
        prognose: prognose,
        ist: ist,
        status: status,
        werk: werk
    };

    messagesToSend.push({
        topic: topic,
        payload: payload,
        qos: 1,
        retain: true
    });
}

return [messagesToSend];

