//Filter (<2 Wochen oder not Done) & Leere Einträge für Maschinen Komponenten ohne Eintrag
function processPayload(msg) {
    // Aktuelles Datum in UTC
    const now = new Date();
    const twoWeeksAgo = new Date(now.getTime() - (14 * 24 * 60 * 60 * 1000));

    // Sammle alle unique Komponenten_Hersteller
    const allManufacturers = new Set(msg.payload.map(item => item.Komponenten_Hersteller));

    // Filtere die Einträge
    const filteredData = msg.payload.filter(item => {
        const startDate = new Date(item.StartDate);
        return startDate >= twoWeeksAgo || item.Done === false;
    });

    // Prüfe welche Hersteller keine Einträge haben
    const presentManufacturers = new Set(filteredData.map(item => item.Komponenten_Hersteller));

    // Erstelle leere Einträge für fehlende Hersteller
    const emptyEntries = Array.from(allManufacturers)
        .filter(manufacturer => !presentManufacturers.has(manufacturer))
        .map(manufacturer => ({
            StartDate: now.toISOString(),
            Description: ' ',
            Done: false,
            Komponenten_Hersteller: manufacturer,
            DoneDate: "",
            Number: manufacturer,
            Summary: "",
            Status: 0,
            Name: "",
            Anlagen_Hersteller: "",
            Werk: "0",
            Kategorie: ""

        }));

    // Kombiniere gefilterte Daten mit leeren Einträgen
    msg.payload = [...filteredData, ...emptyEntries];
    return msg;
}

return processPayload(msg);

