function generateBulkInsertStatement(payload, table) {
    // Check if payload exists and is not empty
    if (!payload || !Array.isArray(payload) || payload.length === 0) {
        node.warn("Payload is empty - skipping database insert");
        return null;
    }

    // Check if first record has machine_id
    if (!payload[0]?.machine_id) {
        node.warn("First record missing machine_id - skipping database insert");
        return null;
    }

    let paramsPerRow = 0;
    let columnNames = '';
    let params = [];

    if (table === 'output') {
        paramsPerRow = 11;
        columnNames = 'timestamp, counter_total, machine_id, counter_maintenance, counter_article, capacity, speed, workpiece_length, workpiece_thickness, workpiece_width, material_id';
        params = payload.flatMap(record => [
            record.timestamp,
            record.counter_total,
            record.machine_id,
            record.counter_maintenance,
            record.counter_article,
            record.capacity,
            record.speed,
            record.workpiece_length,
            record.workpiece_thickness,
            record.workpiece_width,
            record.material_id
        ]);
    }
    else if (table === 'state') {
        paramsPerRow = 3;
        columnNames = 'timestamp, state_id, machine_id';
        params = payload.flatMap(record => [
            record.timestamp,
            record.state_id,
            record.machine_id
        ]);
    }
    else if (table === 'drill_times' || table === 'drill_state') {
        paramsPerRow = 5;
        columnNames = 'timestamp, machine_id, drill_id, basetime, worktime';
        params = payload.flatMap(record => [
            record.timestamp,
            record.machine_id,
            record.drill_id,
            record.basetime,
            record.worktime
        ]);
    }

    let valueStrings = payload.map((_, index) => {
        let start = index * paramsPerRow + 1;
        return `($${start}::timestamptz${[...Array(paramsPerRow-1)].map((_, i) => `, $${start + i + 1}`).join('')})`;
    }).join(',\n');

    msg.query = `INSERT INTO koch.${table}_${payload[0].machine_id} 
                 (${columnNames}) 
                 VALUES ${valueStrings}`;
    msg.params = params;

    return msg;
}

