function getMaxTimestamps(msg) {
    // Ensure msg.machine_ids exists
    if (!msg.machine_ids || !Array.isArray(msg.machine_ids)) {
        node.error("msg.machine_ids is not defined or not an array");
        return null;
    }

    // Initialize the array to store queries
    let queries = [];


    // Generate a query for each machine_id
    msg.machine_ids.forEach(machineId => {
        let prefix = machineId.substring(0, 3);

        // CREATE TABLE für drill_times nur für machine_ids, die mit 'a23' beginnen
