        let query = `
            SELECT '${machineId}' as machine_id,
                (SELECT COALESCE(MAX(timestamp), '1970-01-01') FROM koch.output_${ machineId }) as max_timestamp_output,
                (SELECT COALESCE(MAX(timestamp), '1970-01-01') FROM koch.state_${ machineId }) as max_timestamp_state,
                (SELECT COALESCE(MAX(timestamp), '1970-01-01') FROM koch.drill_times_${ machineId }) as max_timestamp_drill_times`;
        queries.push(query);}
        else {
        let query = `
            SELECT '${machineId}' as machine_id,
            (SELECT COALESCE(MAX(timestamp), '1970-01-01') FROM koch.output_${machineId}) as max_timestamp_output,
            (SELECT COALESCE(MAX(timestamp), '1970-01-01') FROM koch.state_${machineId}) as max_timestamp_state,
            (SELECT '1970-01-01'::timestamptz) as max_timestamp_drill_times`;
        queries.push(query);}
    });

    // Combine all queries into a single query using UNION ALL
    msg.query = queries.join(' UNION ALL ');

    // The result will be an array of objects, each containing machine_id and max_timestamp
    return msg;
}

