function sanitizeColumn(name) {
    var sanitized = name
        .toLowerCase()
        .replace(/[^a-z0-9_]/g, '_')
        .replace(/_+/g, '_')
        .replace(/^_+|_+$/g, '');

    if (sanitized.length > 63) {
        sanitized = sanitized.slice(-63);
    }

    // PG identifiers must start with a letter
    sanitized = sanitized.replace(/^[^a-z]+/, '');

    return sanitized || 'unnamed';
}

