initialize:
// Der Code hier wird ausgeführt,
// wenn der Node gestartet wird

// Set a initial state to see if a message has reached this node.
const errorFlag = flow.get("errorFlag") || false;

func:
// get errorFlag
const errorFlag = flow.get('errorFlag') || false;

// if errorFlag is True, do nothing and set errorFlag to false
if (errorFlag) {
    flow.set('errorFlag', false)
    return null
} else {
    msg.topic = 'control'
    msg.payload = 'peek'
    return msg
}

const buffer = flow.get("buffer") || {};
const now = Date.now();

// Konfiguration
const maxDataAgeHours = env.get('RETENTION_HOURS');  // Max. Alter absolut (z. B. 10 Tage)
const maxDataAgeMs = maxDataAgeHours * 60 * 60 * 1000;

for (let topic in buffer) {
    const messages = buffer[topic];

    if (!messages || messages.length === 0) continue;

    // Finde neuesten Timestamp in diesem Topic
    const maxTs = Math.max(...messages.map(e => e.ts));

    // Filterlogik:
    // 1. Behalte alle mit ts === maxTs (der aktuellste für dieses Topic)
    // 2. Behalte alle, die nicht älter als maxDataAgeMs sind
    // 3. Lösche alle anderen
    buffer[topic] = messages.filter(entry => {
        const isLatest = entry.ts === maxTs;
        const isRecentEnough = (now - entry.ts) <= maxDataAgeMs;
        return isLatest || isRecentEnough;
    });
}

flow.set("buffer", buffer);
return null;

const device_id = msg.payload.device_id;
const buffer_name = `${device_id}_buffer`;
const buffer = flow.get(buffer_name) || {};
const currentTopic = msg.topic;
const currentMsg = msg.payload;
const currentMsgTimestamp = new Date(currentMsg.timestamp).getTime();
let computingTime = flow.get("computingTime") || []

const startTime = Date.now();  // ⏱ Start timing

let merged = {};
merged[currentTopic] = currentMsg;

for (let topic in buffer) {
    if (topic === currentTopic) continue;

    const messages = buffer[topic];
    // Suche die Nachricht mit größtem timestamp ≤ currentMsgTimestamp
    const match = [...messages].reverse().find(entry => entry.timestamp <= currentMsgTimestamp);

    if (match) {
        merged[topic] = match.payload;
    } else {
        // Kein gültiger Match – dann gib nicht weiter
        node.warn("Kein gültiger Match – continue");
        continue;
    }
}

// ⏱ End timing
const endTime = Date.now();
const durationMs = endTime - startTime;
computingTime.push(durationMs)

// Limit to 50 entries (keep newest)
if (computingTime.length > 50) {
    computingTime = computingTime.slice(-50);
}

flow.set("computingTime", computingTime);

// Gib zusammengeführte Nachricht weiter
msg.payload = merged;
return msg;

// To clear all buffers
let buffers = flow.get('all_buffers') || [];
for (let name of buffers) {
    flow.set(name, undefined); // Deletes the buffer variable
}
flow.set('all_buffers', []); // Reset the buffer index
// reset counters
flow.set("counter_in", 0);
flow.set("counter_out", 0);
return null;

// Buffer structure: buffer[topic] = [ { timestamp, payload, arrival_time } ]
const max_messages_per_topic = env.get("BUFFER_SIZE_PER_TOPIC");
const device_id = msg.payload.device_id;

// const device_id_env = env.get("DEVICE_ID")
// Remove message when device id does not fit
// if (device_id != device_id_env) {
//     node.status({ fill: "red", shape: "ring", text: `device_id: ${device_id} does not match DEVICE_ID: ${device_id_env}`});
//     return null
// }

const topic = msg.topic;
const payload = msg.payload;
const buffer_name = `${device_id}_buffer`;

if (!payload.timestamp) return null; // Nachricht ohne Timestamp überspringen

const timestamp = new Date(payload.timestamp).getTime();
const arrival_time = Date.now();

const buffer = flow.get(buffer_name) || {};
// Keep track of created buffers
let buffer_list = flow.get('all_buffers') || [];
if (!buffer_list.includes(buffer_name)) {
    buffer_list.push(buffer_name);
    flow.set('all_buffers', buffer_list);
}

if (!buffer[topic]) {
    buffer[topic] = [];
}

buffer[topic].push({ timestamp, payload, arrival_time });

// Sortiere aufsteigend nach Timestamp
buffer[topic].sort((a, b) => a.timestamp - b.timestamp);

// Optional: beschränke auf letzte 5000 Einträge pro Topic
buffer[topic] = buffer[topic].slice(max_messages_per_topic * -1);

flow.set(buffer_name, buffer);

// Gib Nachricht weiter für delay
return msg;

const device_id = env.get('DEVICE_ID');
const buffer_name = `${device_id}_buffer`;
const buffer = flow.get(buffer_name) || {};

const counts = Object.fromEntries(
    Object.entries(buffer).map(([topic, arr]) => [topic, arr.length])
);

let computingTime = flow.get("computingTime") || [];
const maxDuration = Math.max(...computingTime);

node.status({
    fill: "blue",
    shape: "dot",
    text: `Max computing time of last 50 operations: ${maxDuration}`
});

msg.payload = counts;
return msg
